{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 동물복지위원회 임시회 소집 가능 여부(정기회의 두 번 개최 후)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제5조제7항에 따르면 위원회의 회의는 연 두 차례 개최하되, 위원장이 필요하다고 인정하거나 재적위원 3분의 1 이상의 회의소집 요구가 있을 때에는 임시회를 개최할 수 있다. 재적위원 15명 중 5명은 3분의 1 이상에 해당하므로 임시회 소집 요구 요건을 충족한다. 따라서 정기회의 두 번을 이미 열었더라도 위원장이 필요하다고 인정하거나 재적위원 3분의 1 이상의 요구가 있으면 임시회를 개최할 수 있다.",
          "b_ids": "동물보호:제5조제7항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
